{"command":"cat > prices.py <<'PY'
import json
import urllib.request

BASE = "http://prices.internal/api/v1/price"


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list[str]) -> float:
    """Return the combined live price of all requested SKUs."""
    if not skus:
        return 0

    with urllib.request.urlopen(
        f"{BASE}?skus={','.join(skus)}", timeout=5
    ) as response:
        return float(json.load(response)["total"])
PY"}
